import{_ as o,a0 as p,w as d,s as c,ao as l,I as n,x as s,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 終端使用 inxi 命令獲取各種系統信息 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 終端使用 inxi 命令獲取各種系統信息 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 終端使用 inxi 命令獲取各種系統信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 終端使用 inxi 命令獲取各種系統信息 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20211215 Get All Kind of System Information in Linux Terminal With inxi","title":"在 Linux 終端使用 inxi 命令獲取各種系統信息","tag":"202112","desc":""},"relativePath":"202112/20211215 Get All Kind of System Information in Linux Terminal With inxi.md","filePath":"[post].md"}'),r={name:"202112/20211215 Get All Kind of System Information in Linux Terminal With inxi.md"};function h(g,i,u,b,k,m){const e=p("Link");return d(),c("div",null,[i[18]||(i[18]=l(`<h1 id="在-linux-終端使用-inxi-命令獲取各種系統信息" tabindex="-1">在 Linux 終端使用 inxi 命令獲取各種系統信息 <a class="header-anchor" href="#在-linux-終端使用-inxi-命令獲取各種系統信息" aria-label="Permalink to “在 Linux 終端使用 inxi 命令獲取各種系統信息”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202112/17/134920bzuqfbwbqswcif33.jpg" alt=""></p><p><code>inix</code> 是一個用於獲取 Linux 系統信息的終端命令。能夠獲取軟件和硬件的詳細信息，比如計算機型號、內核版本、發行版號以及桌面環境等信息，甚至可以讀取主存模組佔用主板的哪塊 RAM 卡槽等詳細信息。</p><p><code>inxi</code> 還可以用於監控系統中正在消耗 CPU 或者內存資源的進程。</p><p>在本文中，我將展示使用 <code>inxi</code> 命令獲取系統信息的常用操作。</p><p>首先，我將展示下如何安裝 <code>inxi</code> 命令。</p><h3 id="在-linux-上安裝-inxi" tabindex="-1">在 Linux 上安裝 inxi <a class="header-anchor" href="#在-linux-上安裝-inxi" aria-label="Permalink to “在 Linux 上安裝 inxi”">​</a></h3><p><code>inxi</code> 是一個非常流行的工具，所以在大多數 Linux 發行版倉庫中都可以輕鬆獲取到該工具。不過還沒有流行到各大 Linux 發行版默認就安裝了該軟件，所以需要我們自己安裝一下。</p><p>在 Ubuntu/Debian 發行版系統中，安裝命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install inxi</span></span></code></pre></div><p>在 Fedora/RHEL8-based 等發行版中，安裝命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install -y epel-release</span></span>
<span class="line"><span>sudo dnf install -y inxi</span></span></code></pre></div><p>在 <code>Arch Linux</code> 以及它的派生分支版本中，安裝命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo pacman -S inxi</span></span></code></pre></div><h3 id="使用-inxi-獲取系統信息" tabindex="-1">使用 inxi 獲取系統信息 <a class="header-anchor" href="#使用-inxi-獲取系統信息" aria-label="Permalink to “使用 inxi 獲取系統信息”">​</a></h3><p>你可以在終端運行 <code>inxi</code> 命令來總體瀏覽下系統信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi</span></span></code></pre></div><p>如下圖所示，運行 <code>inxi</code> 命令可以簡要瀏覽 CPU、時鐘頻率（<code>speed/min/max</code>）、內核（<code>Kernel</code>）、內存（<code>Mem</code>）、磁盤存儲空間（<code>Storage</code>）、運行進程數量（<code>Procs</code>）以及 Shell 等信息。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/01_inxi.webp?resize=800%2C450&amp;ssl=1" alt="The default output of inxi command"></p><p>使用 <code>-b</code> 參數可以獲取更為詳細的系統信息。<code>-b</code> 參數會讀取更多有關 CPU、驅動器、當前運行進程、主板 UEFI 版本、GPU、顯示分辨率以及網絡設備等詳細信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -b</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/02_inxi_flag_b.webp?resize=800%2C450&amp;ssl=1" alt="Detailed hardware and software information about machine as reported by inxi"></p><p>類似 <code>-b</code> 參數使用方法，<code>inxi</code> 還有許多其他的參數可供使用。你可以綜合使用這些參數來獲取你關心的信息。</p><p>讓我們看幾個實例。</p><h3 id="獲取音頻設備信息" tabindex="-1">獲取音頻設備信息 <a class="header-anchor" href="#獲取音頻設備信息" aria-label="Permalink to “獲取音頻設備信息”">​</a></h3><p>使用 <code>-A</code> 參數可以獲取有關音頻（輸出）設備信息，包括物理音頻（輸出）設備、聲音服務器以及音頻驅動等詳細信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -A</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/03_inxi_flag_a.webp?resize=800%2C450&amp;ssl=1" alt="Output of inxi command when “-A” flag is used"></p><h3 id="獲取電池信息" tabindex="-1">獲取電池信息 <a class="header-anchor" href="#獲取電池信息" aria-label="Permalink to “獲取電池信息”">​</a></h3><p>使用 <code>-B</code> 參數，可以獲取有關電池的信息（如果安裝了電池）。你將讀取到例如以 <code>Wh</code>（瓦特小時）為單位的當前電池電量和狀況。</p><p>因為我使用的是台式機，所以這裏僅僅作為一個示例，讓我們看看使用 <code>inxi -B</code> 會輸出什麼。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Battery:   ID-1: BAT0 charge: 50.0 Wh (100.0%) condition: 50.0/50.0</span></span></code></pre></div><h3 id="獲取-cpu-信息" tabindex="-1">獲取 CPU 信息 <a class="header-anchor" href="#獲取-cpu-信息" aria-label="Permalink to “獲取 CPU 信息”">​</a></h3><p><code>-C</code> 參數用於獲取有關 CPU 的詳細信息。比如包括 CPU 緩存大小、頻率（單位 <code>MHz</code>，如果有多核，會顯示每個核心的頻率）、核心數、CPU 型號以及 CPU 是 32 位還是 64 位。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -C</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/04_inxi_flag_c.webp?resize=800%2C450&amp;ssl=1" alt="Detailed CPU information displayed by inxi"></p><p>注意，如果是在虛擬機中使用 <code>inix -C</code>，<code>inxi</code> 讀取到的 <code>CPU</code> 的最大和最小頻率可能異常。下面是一個在四核 Debian 11 虛擬機中使用 <code>-C</code> 參數的示例輸出。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/05_inxi_flag_c_vm.webp?resize=800%2C396&amp;ssl=1" alt="An example output of using the “-C” flag in a Virtual Machine"></p><h3 id="獲取更多的系統信息" tabindex="-1">獲取更多的系統信息 <a class="header-anchor" href="#獲取更多的系統信息" aria-label="Permalink to “獲取更多的系統信息”">​</a></h3><p>使用 <code>-F</code> 參數可以獲取更詳細的系統信息（類似 <code>-b</code> 參數，但會更為詳細）。幾乎囊括了所有層次的系統信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -F</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/06_inxi_flag_f.webp?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="獲取圖形顯示相關信息" tabindex="-1">獲取圖形顯示相關信息 <a class="header-anchor" href="#獲取圖形顯示相關信息" aria-label="Permalink to “獲取圖形顯示相關信息”">​</a></h3><p><code>-G</code> 參數可以獲取和圖形相關的信息。</p><p>它會顯示所有的圖形設備（GPU）、正在使用的 GPU 驅動（有助於檢查是否使用 Nvidia 驅動還是 nouveau 驅動）、顯示輸出分辨率和驅動程序版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -G</span></span></code></pre></div><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/07_inxi_flag_g.webp?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="獲取運行進程信息" tabindex="-1">獲取運行進程信息 <a class="header-anchor" href="#獲取運行進程信息" aria-label="Permalink to “獲取運行進程信息”">​</a></h3><p><code>-I</code> 參數（大寫字母 <code>i</code>）顯示正在運行的進程、當前 shell 、內存（內存使用情況）以及 <code>inxi</code> 版本號等信息。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/inxi-get-running-process-info.png?resize=768%2C272&amp;ssl=1" alt="inxi get running process info"></p><h3 id="獲取內存信息" tabindex="-1">獲取內存信息 <a class="header-anchor" href="#獲取內存信息" aria-label="Permalink to “獲取內存信息”">​</a></h3><p>可能你已經猜到了，<code>-m</code> 參數可以獲取與內存相關的信息。</p><p>它讀取了如總可用內存、最大內存容量（硬件或 CPU 支持的）、主板物理內存插槽數、是否存在 ECC、插入的內存插槽，以及枚舉每個插槽中運行的內存模組的大小和運行速度等信息。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -m</span></span></code></pre></div><p>要使用 <code>-m</code> 參數獲取更詳細的信息，例如最大容量、每個插槽的內存模組信息等，需要超級用户權限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo inxi -m</span></span></code></pre></div><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/08_inxi_flag_m.webp?resize=800%2C450&amp;ssl=1" alt=""></p><p>如果只是希望簡短的輸出內存信息，可以使用 <code>-memory-short</code> 參數。</p><p>使用 <code>-memroy-short</code> 參數將會只顯示總內存以及當前已使用的內存量。</p><h3 id="查看正在使用的包存儲庫" tabindex="-1">查看正在使用的包存儲庫 <a class="header-anchor" href="#查看正在使用的包存儲庫" aria-label="Permalink to “查看正在使用的包存儲庫”">​</a></h3><p>當使用 <code>-r</code> 參數時，會列舉當前正在使用的包管理倉庫或者更新本地倉庫緩存中的所有存儲庫列表。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/package-repo-info-with-inxi.png?resize=800%2C339&amp;ssl=1" alt="List of repositories in use"></p><h3 id="獲取-raid-設備信息" tabindex="-1">獲取 RAID 設備信息 <a class="header-anchor" href="#獲取-raid-設備信息" aria-label="Permalink to “獲取 RAID 設備信息”">​</a></h3><p><code>-R</code> 參數用於獲取所有 RAID 設備相關信息。</p><p>令人驚喜的是，它甚至顯示了有關 ZFS RAID（默認情況下，多數 Linux 系統不包含該文件系統）的信息。它顯示了 RAID 設備上文件系統的詳細信息、狀態（包含離線狀態、總大小和可用大小等）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -R</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/09_inxi_flag_r.webp?resize=800%2C450&amp;ssl=1" alt=""></p><h3 id="在-linux-終端中查詢天氣-對-這是可以的" tabindex="-1">在 Linux 終端中查詢天氣（對，這是可以的） <a class="header-anchor" href="#在-linux-終端中查詢天氣-對-這是可以的" aria-label="Permalink to “在 Linux 終端中查詢天氣（對，這是可以的）”">​</a></h3><p>利用 <code>-W</code> 參數，你可以查詢地球上任何地方的天氣情況。</p><p><code>-W</code> 參數後面，需要攜帶以下中的任一一個體現位置的信息</p><ul><li>郵政編碼</li><li>緯度</li><li>城市（及州）、國家（不能含有空格，使用 “+” 替換空格）</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -W Baroda,India</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/12_inxi_flag_w.webp?resize=800%2C450&amp;ssl=1" alt="Use of the “-W” flag with inxi followed by the city,country location descriptor"></p><h3 id="監控系統資源使用情況" tabindex="-1">監控系統資源使用情況 <a class="header-anchor" href="#監控系統資源使用情況" aria-label="Permalink to “監控系統資源使用情況”">​</a></h3><p><code>inxi</code> 除了提供有關已安裝的硬件和驅動的信息外，還可以用於資源監控。</p><p>使用 <code>-t</code> 參數可以顯示進程信息。你還可以可選項 <code>-c</code> （用於 CPU）和 <code>-m</code>（用於內存）。這些選項結合使用可以按指定數量列出進程信息。</p><p>下面是一些使用 <code>-t</code> 參數監控資源信息的示例。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -t</span></span></code></pre></div><p>命令 <code>inxi -t</code> 默認效果等同於 <code>inxi -t cm5</code> 的效果。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/10_inxi_flag_t.webp?resize=800%2C450&amp;ssl=1" alt="No difference in output of “inti -t” and “inxi -t cm5”"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inxi -t cm10</span></span></code></pre></div><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/11_inxi_flag_t_cm10.webp?resize=800%2C450&amp;ssl=1" alt=""></p>`,82)),n("p",null,[i[1]||(i[1]=s("偶爾需要監控資源使用情況時，該工具挺管用。如果需要更多的資源監控功能，則推薦使用 ",-1)),a(e,{href:"https://itsfoss.com/linux-system-monitoring-tools/"},{default:t(()=>[...i[0]||(i[0]=[s("專用系統資源監控工具",-1)])]),_:1}),i[2]||(i[2]=s("。",-1))]),i[19]||(i[19]=l('<h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>對於需要診斷計算機問題以及獲取那些並不熟悉的軟硬件信息的人來説，<code>inxi</code> 工具是十分便利且有用的。它能識別那些消耗 CPU、內存的進程；可以檢查是否安裝了合適的圖形驅動程序、主板 UEFI/BIOS 是否需要更新等等。</p><p>事實上，在 <code>inxi</code> 開源社區論壇上，我們要求那些尋求幫助的成員提供 <code>inxi</code> 命令輸出內容以便判斷他們當前正在使用什麼樣的系統環境。</p><p>我知道也有其他的工具可以讀取 Linux 上的硬件信息，不過 <code>inxi</code> 同時能讀取硬件和軟件信息，這也是我喜歡它的地方所在。</p><p>你使用 <code>inxi</code> 或者其他工具麼？歡迎在評論區留言分享交流。</p><hr>',6)),n("p",null,[i[4]||(i[4]=s("via: ",-1)),a(e,{href:"https://itsfoss.com/inxi-system-info-linux/"},{default:t(()=>[...i[3]||(i[3]=[s("https://itsfoss.com/inxi-system-info-linux/",-1)])]),_:1})]),n("p",null,[i[9]||(i[9]=s("作者：",-1)),a(e,{href:"https://itsfoss.com/author/pratham/"},{default:t(()=>[...i[5]||(i[5]=[s("Pratham Patel",-1)])]),_:1}),i[10]||(i[10]=s(" 選題：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...i[6]||(i[6]=[s("lujun9972",-1)])]),_:1}),i[11]||(i[11]=s(" 譯者：",-1)),a(e,{href:"https://github.com/jrglinux"},{default:t(()=>[...i[7]||(i[7]=[s("jrglinux",-1)])]),_:1}),i[12]||(i[12]=s(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...i[8]||(i[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[i[15]||(i[15]=s("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...i[13]||(i[13]=[s("LCTT",-1)])]),_:1}),i[16]||(i[16]=s(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...i[14]||(i[14]=[s("Linux中國",-1)])]),_:1}),i[17]||(i[17]=s(" 榮譽推出",-1))])])}const y=o(r,[["render",h]]);export{C as __pageData,y as default};
